/** The encrypted channel to the desktop native messaging host.
 *
 * Mirrors native_host.py byte-for-byte (the known-answer vectors in
 * tests/fixtures/channel-vectors.json are generated by the Python
 * implementation and must match this one exactly):
 *
 * - X25519 key agreement between the extension's pairing keypair and
 *   the desktop host's pinned public key.
 * - HKDF-SHA256 (salt = client_nonce ‖ server_nonce, info =
 *   "mykey-ext-v1 e2h" / "mykey-ext-v1 h2e") → one AES-256 key per
 *   direction.
 * - Every message is AES-256-GCM sealed; nonce = 3-letter direction
 *   prefix + NUL + 8-byte big-endian counter; AAD binds protocol,
 *   direction, session id and counter. Counters are strict: any gap
 *   or replay ends the session.
 * - Plaintext is canonical JSON (sorted keys, Python-compatible
 *   string escaping) — the same canonical form the vault uses.
 */

import { x25519 } from "@noble/curves/ed25519.js";
import { hkdf } from "@noble/hashes/hkdf.js";
import { sha256 } from "@noble/hashes/sha2.js";
import {
  b64decode,
  b64encode,
  utf8Decode,
  utf8Encode,
} from "../../src/vault/encoding.js";

export const PROTOCOL = "mykey-ext-v1";
export const NATIVE_HOST_NAME = "com.usemykey.mykey";

export class ChannelError extends Error {}

export class HostRefused extends Error {
  constructor(
    readonly code: string,
    message: string,
  ) {
    super(message);
  }
}

/** Canonical JSON, byte-identical to Python's
 * json.dumps(obj, sort_keys=True, separators=(",", ":")) with its
 * default ensure_ascii escaping. */
export function canonicalJson(value: unknown): string {
  if (value === null) return "null";
  if (typeof value === "boolean") return value ? "true" : "false";
  if (typeof value === "number") {
    if (!Number.isInteger(value)) {
      throw new ChannelError("channel messages carry integers only");
    }
    return String(value);
  }
  if (typeof value === "string") return escapeJsonString(value);
  if (Array.isArray(value)) {
    return "[" + value.map(canonicalJson).join(",") + "]";
  }
  if (typeof value === "object") {
    const entries = Object.entries(value as Record<string, unknown>)
      .filter(([, v]) => v !== undefined)
      .sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0));
    return (
      "{" +
      entries
        .map(([k, v]) => escapeJsonString(k) + ":" + canonicalJson(v))
        .join(",") +
      "}"
    );
  }
  throw new ChannelError(`uncanonical value: ${typeof value}`);
}

function escapeJsonString(s: string): string {
  let out = '"';
  for (let i = 0; i < s.length; i++) {
    const code = s.charCodeAt(i);
    const ch = s[i] as string;
    if (ch === '"') out += '\\"';
    else if (ch === "\\") out += "\\\\";
    else if (ch === "\n") out += "\\n";
    else if (ch === "\r") out += "\\r";
    else if (ch === "\t") out += "\\t";
    else if (ch === "\b") out += "\\b";
    else if (ch === "\f") out += "\\f";
    else if (code < 0x20 || code > 0x7e) {
      out += "\\u" + code.toString(16).padStart(4, "0");
    } else out += ch;
  }
  return out + '"';
}

export function deriveSessionKeys(
  sharedSecret: Uint8Array,
  clientNonce: Uint8Array,
  serverNonce: Uint8Array,
): { e2h: Uint8Array; h2e: Uint8Array } {
  const salt = new Uint8Array(clientNonce.length + serverNonce.length);
  salt.set(clientNonce, 0);
  salt.set(serverNonce, clientNonce.length);
  return {
    e2h: hkdf(sha256, sharedSecret, salt, utf8Encode(`${PROTOCOL} e2h`), 32),
    h2e: hkdf(sha256, sharedSecret, salt, utf8Encode(`${PROTOCOL} h2e`), 32),
  };
}

function nonceFor(direction: "e2h" | "h2e", seq: number): Uint8Array {
  const nonce = new Uint8Array(12);
  nonce.set(utf8Encode(direction), 0);
  nonce[3] = 0;
  const view = new DataView(nonce.buffer);
  view.setBigUint64(4, BigInt(seq), false);
  return nonce;
}

function aadFor(
  direction: "e2h" | "h2e",
  sessionId: string,
  seq: number,
): Uint8Array {
  const head = utf8Encode(`${PROTOCOL}|${direction}|${sessionId}|`);
  const aad = new Uint8Array(head.length + 8);
  aad.set(head, 0);
  new DataView(aad.buffer).setBigUint64(head.length, BigInt(seq), false);
  return aad;
}

export interface SealedFrame {
  kind: "sealed";
  session: string;
  seq: number;
  nonce: string;
  ct: string;
}

export async function sealMessage(
  key: Uint8Array,
  direction: "e2h" | "h2e",
  sessionId: string,
  seq: number,
  message: Record<string, unknown>,
): Promise<SealedFrame> {
  const nonce = nonceFor(direction, seq);
  const cryptoKey = await crypto.subtle.importKey(
    "raw",
    key as BufferSource,
    "AES-GCM",
    false,
    ["encrypt"],
  );
  const ct = await crypto.subtle.encrypt(
    {
      name: "AES-GCM",
      iv: nonce as BufferSource,
      additionalData: aadFor(direction, sessionId, seq) as BufferSource,
    },
    cryptoKey,
    utf8Encode(canonicalJson(message)) as BufferSource,
  );
  return {
    kind: "sealed",
    session: sessionId,
    seq,
    nonce: b64encode(nonce),
    ct: b64encode(new Uint8Array(ct)),
  };
}

export async function openMessage(
  key: Uint8Array,
  direction: "e2h" | "h2e",
  sessionId: string,
  frame: SealedFrame,
): Promise<Record<string, unknown>> {
  if (frame.kind !== "sealed" || frame.session !== sessionId) {
    throw new ChannelError("frame is not for this session");
  }
  const nonce = b64decode(frame.nonce);
  const expected = nonceFor(direction, frame.seq);
  if (
    nonce.length !== expected.length ||
    !nonce.every((b, i) => b === expected[i])
  ) {
    throw new ChannelError("nonce does not match sequence");
  }
  const cryptoKey = await crypto.subtle.importKey(
    "raw",
    key as BufferSource,
    "AES-GCM",
    false,
    ["decrypt"],
  );
  let pt: ArrayBuffer;
  try {
    pt = await crypto.subtle.decrypt(
      {
        name: "AES-GCM",
        iv: nonce as BufferSource,
        additionalData: aadFor(direction, sessionId, frame.seq) as BufferSource,
      },
      cryptoKey,
      b64decode(frame.ct) as BufferSource,
    );
  } catch {
    throw new ChannelError("frame failed to open");
  }
  const message = JSON.parse(utf8Decode(new Uint8Array(pt))) as unknown;
  if (typeof message !== "object" || message === null) {
    throw new ChannelError("frame plaintext is not an object");
  }
  return message as Record<string, unknown>;
}

/** Grouped-hex SHA-256 fingerprint — byte-identical presentation
 * to extpair.extension_fingerprint on the desktop. */
export function keyFingerprint(x25519Pub: Uint8Array): string {
  const digest = sha256(x25519Pub);
  const hex = Array.from(digest)
    .map((b) => b.toString(16).padStart(2, "0"))
    .join("");
  const groups: string[] = [];
  for (let i = 0; i < 32; i += 4) groups.push(hex.slice(i, i + 4));
  return groups.join(":");
}

export interface FrameTransport {
  post(frame: Record<string, unknown>): void;
  onFrame(cb: (frame: Record<string, unknown>) => void): void;
  onClose(cb: () => void): void;
  close(): void;
}

export interface HelloAck {
  protocol: string;
  unlocked: boolean;
  vaultConfigured: boolean;
  scopes: string[];
}

interface PendingCall {
  resolve: (value: Record<string, unknown>) => void;
  reject: (err: Error) => void;
}

/** One live session with the desktop host. */
export class HostSession {
  private sendSeq = 0;
  private expectSeq = 0;
  private nextId = 1;
  private pending = new Map<number, PendingCall>();
  private closed = false;
  private closeCbs: Array<() => void> = [];

  private constructor(
    private transport: FrameTransport,
    private keys: { e2h: Uint8Array; h2e: Uint8Array },
    readonly sessionId: string,
    readonly ack: HelloAck,
  ) {
    transport.onFrame((frame) => {
      void this.handleFrame(frame);
    });
    transport.onClose(() => this.teardown(new ChannelError("host closed")));
  }

  static async connect(
    transport: FrameTransport,
    opts: {
      extensionId: string;
      privateKey: Uint8Array;
      pinnedHostPub?: Uint8Array;
    },
  ): Promise<HostSession> {
    const clientNonce = new Uint8Array(32);
    crypto.getRandomValues(clientNonce);
    const publicKey = x25519.getPublicKey(opts.privateKey);
    const firstFrame = new Promise<Record<string, unknown>>(
      (resolve, reject) => {
        let done = false;
        transport.onFrame((frame) => {
          if (!done) {
            done = true;
            resolve(frame);
          }
        });
        transport.onClose(() =>
          reject(new ChannelError("host closed during handshake")),
        );
      },
    );
    transport.post({
      kind: "hello",
      extension_id: opts.extensionId,
      ext_pub: b64encode(publicKey),
      client_nonce: b64encode(clientNonce),
    });
    const hello = await firstFrame;
    if (hello.kind === "fatal") {
      throw new HostRefused(
        String(hello.code ?? "pairing_refused"),
        String(hello.message ?? "pairing refused"),
      );
    }
    if (hello.kind !== "hello") {
      throw new ChannelError("unexpected first frame from host");
    }
    const hostPub = b64decode(String(hello.host_pub));
    if (
      opts.pinnedHostPub &&
      (hostPub.length !== opts.pinnedHostPub.length ||
        !hostPub.every((b, i) => b === (opts.pinnedHostPub as Uint8Array)[i]))
    ) {
      throw new ChannelError(
        "the desktop host's key does not match the key pinned at " +
          "pairing — connection refused",
      );
    }
    const serverNonce = b64decode(String(hello.server_nonce));
    const shared = x25519.getSharedSecret(opts.privateKey, hostPub);
    const keys = deriveSessionKeys(shared, clientNonce, serverNonce);
    const expectSession = Array.from(
      sha256(new Uint8Array([...clientNonce, ...serverNonce])),
    )
      .map((b) => b.toString(16).padStart(2, "0"))
      .join("")
      .slice(0, 32);
    if (hello.session !== expectSession) {
      throw new ChannelError("session id mismatch");
    }
    const session = new HostSession(
      transport,
      keys,
      expectSession,
      // placeholder, replaced after the ack opens below
      { protocol: PROTOCOL, unlocked: false, vaultConfigured: false, scopes: [] },
    );
    const ackRaw = await session.openNext(hello.ack as SealedFrame);
    const ack: HelloAck = {
      protocol: String(ackRaw.protocol ?? ""),
      unlocked: Boolean(ackRaw.unlocked),
      vaultConfigured: Boolean(ackRaw.vault_configured),
      scopes: Array.isArray(ackRaw.scopes) ? (ackRaw.scopes as string[]) : [],
    };
    if (ack.protocol !== PROTOCOL) {
      throw new ChannelError(`protocol mismatch: ${ack.protocol}`);
    }
    (session as { ack: HelloAck }).ack = ack;
    return session;
  }

  private async openNext(frame: SealedFrame): Promise<Record<string, unknown>> {
    if (frame.seq !== this.expectSeq) {
      throw new ChannelError(
        `sequence mismatch: expected ${this.expectSeq}, got ${frame.seq}`,
      );
    }
    const message = await openMessage(
      this.keys.h2e,
      "h2e",
      this.sessionId,
      frame,
    );
    this.expectSeq += 1;
    return message;
  }

  private async handleFrame(frame: Record<string, unknown>): Promise<void> {
    if (this.closed) return;
    try {
      const message = await this.openNext(frame as unknown as SealedFrame);
      const id = typeof message.id === "number" ? message.id : -1;
      const pending = this.pending.get(id);
      if (pending) {
        this.pending.delete(id);
        if (message.kind === "error") {
          pending.reject(
            new HostRefused(
              String(message.code ?? "error"),
              String(message.message ?? "the host refused"),
            ),
          );
        } else {
          pending.resolve(message);
        }
      }
    } catch (err) {
      this.teardown(err instanceof Error ? err : new ChannelError(String(err)));
    }
  }

  async call(
    kind: string,
    fields: Record<string, unknown> = {},
  ): Promise<Record<string, unknown>> {
    if (this.closed) throw new ChannelError("session is closed");
    const id = this.nextId++;
    const frame = await sealMessage(this.keys.e2h, "e2h", this.sessionId,
      this.sendSeq, { ...fields, kind, id });
    this.sendSeq += 1;
    const result = new Promise<Record<string, unknown>>((resolve, reject) => {
      this.pending.set(id, { resolve, reject });
    });
    this.transport.post(frame as unknown as Record<string, unknown>);
    return result;
  }

  onClose(cb: () => void): void {
    this.closeCbs.push(cb);
  }

  close(): void {
    this.teardown(new ChannelError("session closed by the extension"));
    this.transport.close();
  }

  private teardown(err: Error): void {
    if (this.closed) return;
    this.closed = true;
    for (const pending of this.pending.values()) pending.reject(err);
    this.pending.clear();
    for (const cb of this.closeCbs) cb();
  }

  /** Test/inspection hook: nothing here may ever hold a secret —
   * pending calls are promises, not payloads. */
  inspect(): { pendingCalls: number; closed: boolean; sendSeq: number } {
    return {
      pendingCalls: this.pending.size,
      closed: this.closed,
      sendSeq: this.sendSeq,
    };
  }
}
